  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 255);
  brush.beginShape(0.5);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 200);
  brush.endShape(true);

  // Green hills
  brush.fill("#228B22", 200);
  brush.beginShape(0.7);
  brush.vertex(0, 50);
  brush.vertex(400, 50);
  brush.vertex(200, 150);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 255);
  brush.beginShape(0.8);
  brush.vertex(150, 100);
  brush.vertex(250, 100);
  brush.vertex(200, 50);
  brush.endShape(true);
}

